describe('every example', () => {
  it('there are at least 24 examples with firmware and 3 analog-only ones', () => {
    expect(descriptors.filter((d) => d.firmware).length).toBeGreaterThanOrEqual(24)
    expect(descriptors.filter((d) => !d.firmware).length).toBeGreaterThanOrEqual(3)
  })

  it('content is Taiwan-usage Traditional Chinese; titles / summaries / tags / notes carry no English words', () => {
    const leaks: string[] = []
    for (const d of descriptors) {
      for (const [k, s] of [
        ['title', d.title],
        ['summary', d.summary],
        ['description', d.description],
        ['simulationNote', d.simulationNote ?? ''],
        ...d.tags.map((tag) => ['tag', tag]),
      ] as const) {
        if (!s) continue
        if (k !== 'tag') expect(CJK.test(s), `${d.id} ${k} is zh-TW`).toBe(true)
        expect(MAINLAND_TERMS.filter((m) => s.includes(m)), `${d.id} ${k}: mainland terms`).toEqual([])
        expect(halfWidthPunctuation(s.replace(/`[^`]*`/g, '')), `${d.id} ${k}: half-width punctuation`).toEqual([])
        // UI copy, checked like scripts/i18n-audit.mjs (description: outside `code` spans)
        const words = auditLeaks(s)
        if (words.length) leaks.push(`${d.id} ${k}: ${words.join(' ')}`)
      }
      if (d.simulation === 'partial') expect(d.simulationNote, `${d.id}: partial needs a note`).toBeTruthy()
    }
    expect(leaks).toEqual([])
  })

  it('the library UI texts have zh-TW entries (sections, difficulty, instruments, legacy examples)', () => {
    __setLangForTests('zh-TW')
    try {
      for (const c of EXAMPLE_CATEGORIES) expect(hasTranslation(`${EXAMPLE_CATEGORY_NAMES[c]}|example category`), c).toBe(true)
      for (const [k, v] of Object.entries(EXAMPLE_DIFFICULTY_NAMES)) expect(hasTranslation(`${v}|difficulty`), k).toBe(true)
      for (const [k, v] of Object.entries(EXAMPLE_INSTRUMENT_NAMES)) expect(hasTranslation(`${v}|example instrument`), k).toBe(true)
      for (const ex of LIBRARY.filter((e) => e.localized)) {
        for (const s of [ex.title, ex.summary, ex.description]) expect(hasTranslation(s), s).toBe(true)
      }
    } finally {
      __setLangForTests('zh-TW')
    }
  })
})

/** Run one example: parse, verify, ERC, simulate, behavior. */
function checkExample(d: Descriptor): void {
  const p = readProject(d.id)

  // ---- firmware: byte-identical to firmware/dist
  if (d.firmware) {
    expect(p.firmware.map((f) => f.componentId)).toEqual(['U1'])
    const dist = new Uint8Array(readFileSync(join(DIST, `${d.firmware}.elf`)))
    expect(
      p.firmware[0].sha256,
      `${d.id}: the embedded ${d.firmware}.elf differs from firmware/dist — re-run node scripts/build-examples.mjs`,
    ).toBe(sha256(dist))
    expect(p.firmware[0].name).toBe(`${d.firmware}.elf`)
  } else {
    expect(p.firmware).toEqual([])
  }

  // ---- layout
  const v = validateLayout(p.layout)
  expect(v.errors).toEqual([])
  expect(v.warnings, `${d.id}: layout warnings`).toEqual([])
  expect(p.layout.name).toBe(d.title)

  // ---- ERC: no errors; only the risks the example declares
  const erc = runErc(p.layout)
  const summary = erc.map((f) => `${f.level} ${f.rule}: ${f.message}`).join('\n')
  expect(erc.filter((f) => f.level === 'error'), summary).toEqual([])
  const risks = [...new Set(erc.filter((f) => f.level === 'risk').map((f) => f.rule))].sort()
  expect(risks, summary).toEqual([...(d.ercRisks ?? [])].sort())

  // ---- instruments point at real things
  const comps = new Map(p.layout.components.map((c) => [c.id, c]))
  const chans = p.instruments?.logicChannels ?? []
  for (const ch of chans) {
    if (ch.source.kind === 'mcu-pin') {
      const c = comps.get(ch.source.componentId)
      expect(c, `${d.id}: channel ${ch.index}`).toBeDefined()
      expect(getEntry(c!.type)?.mcu?.pinMap[ch.source.pin], `${d.id}: channel ${ch.index} pin ${ch.source.pin}`).toBeDefined()
    } else if (ch.source.kind === 'probe') {
      expect(comps.get(ch.source.componentId)?.type).toBe('logic_probe')
    }
  }
  for (const dec of (p.instruments?.logicView?.decoders ?? []) as { channels: Record<string, number> }[]) {
    for (const idx of Object.values(dec.channels)) expect(chans.some((c) => c.index === idx), `${d.id}: decoder channel ${idx}`).toBe(true)
  }

  // ---- simulate
  expect(d.expect.seconds).toBeGreaterThanOrEqual(0.5)
  expect(d.expect.seconds).toBeLessThanOrEqual(2)
  const r = new Run(p)
  try {
    r.to(d.expect.seconds)
    expect(r.errors(), `${d.id}: runtime errors`).toEqual([])
    if (d.firmware) {
      const mcu = r.co.mcu('U1')
      expect(mcu?.powered, `${d.id}: MCU powered`).toBe(true)
      // UART: the example's own expectation, else the firmware contract's boot text
      const boot = MANIFEST[d.firmware]?.checks?.boot ?? {}
      const ports = new Set([...Object.keys(boot), ...Object.keys(d.expect.uart ?? {})])
      for (const port of ports) {
        const got = r.uart(port)
        const own = d.expect.uart?.[port]
        if (own !== undefined) {
          expect(got.startsWith(own), `${d.id} ${port}: ${JSON.stringify(got.slice(0, 300))}`).toBe(true)
        } else {
          const spec = boot[port]
          if (typeof spec === 'string') expect(got.startsWith(spec), `${d.id} ${port} boot: ${JSON.stringify(got.slice(0, 300))}`).toBe(true)
          else expect(new RegExp(spec.match.replace(/\$$/, '')).test(got), `${d.id} ${port} boot /${spec.match}/: ${JSON.stringify(got.slice(0, 300))}`).toBe(true)
        }
      }
    }
    const behavior = BEHAVIOR[d.id]
    expect(behavior, `${d.id}: no behavior check`).toBeDefined()
    behavior(r)
    expect(r.errors(), `${d.id}: runtime errors after the behavior run`).toEqual([])
  } finally {
    r.co.dispose()
  }
}

describe('examples run on the real simulation', () => {
  const files = readdirSync(join(DIR, 'src'))
    .filter((x) => x.endsWith('.example.mjs'))
    .map((x) => x.slice(0, -'.example.mjs'.length))
    .sort()
  for (const id of files) {
    it(id, { timeout: 180_000 }, () => {
      const d = descriptors.find((x) => x.id === id)
      expect(d).toBeDefined()
      checkExample(d!)
    })
  }
})

describe('Blue Pill bench geometry (examples/embedded/src/lib.mjs)', () => {
  it('BP_TAP matches the catalog footprint of a Blue Pill at h10', async () => {
    const lib = (await import(pathToFileURL(join(DIR, 'src/lib.mjs')).href)) as { BP_TAP: Record<string, string> }
    const BP = { id: 'U1', type: 'stm32_bluepill', at: 'h10' }
    const entry = CATALOG.stm32_bluepill
    const holes = componentPinHoles(BP, entry)!
    entry.pins.forEach((pin, i) => {
      const h = holes[i]
      if (!h || h.kind !== 'strip') throw new Error(pin)
      expect(lib.BP_TAP[pin], pin).toBe(formatHole({ ...h, row: h.row === 'c' ? 'a' : 'j' }))
    })
  })
})

